  fields={'derm_image_type':('derm 图片类型 / Image type',['未审阅 / Unreviewed','皮肤镜 / Dermoscopic','临床照片 / Clinical','其他 / Other','无法判断 / Cannot determine']),'clinic_image_type':('clinic 图片类型 / Image type',['未审阅 / Unreviewed','皮肤镜 / Dermoscopic','临床照片 / Clinical','其他 / Other','无法判断 / Cannot determine']),'assessable':('是否可判断 / Assessable',['未审阅 / Unreviewed','可以 / Yes','部分 / Partly','无法 / No']),'obvious_input_anomaly':('明显输入异常 / Obvious input anomaly',['未审阅 / Unreviewed','未见明显异常 / None apparent','疑似，需说明 / Suspected; explain','无法判断 / Cannot determine']),'status':('审阅状态 / Review status',['UNREVIEWED','REVIEWED_PENDING_DECISION','REVIEWED'])}
  for key,(label,opts) in fields.items():body+='<label>'+label+'<select data-case="'+rid+'" data-field="'+key+'">'+''.join('<option>'+e(opt)+'</option>' for opt in opts)+'</select></label>'
  for key,label in [('reviewer','审阅者 / Reviewer'),('reviewed_at','日期 / Date')]:body+='<label>'+label+'<input data-case="'+rid+'" data-field="'+key+'"></label>'
